<script setup lang="ts">
import { reactive,ref,computed,watch,onMounted,onUnmounted,nextTick } from 'vue';
import { Save,Plus,Trash2,Image,Upload,Monitor,Music,FileText,Megaphone,ChevronDown,RotateCcw,Images,Blocks } from '@lucide/vue';
import { desk,safely,saveProject,apiPath,binary,blob,request,operation,loadProject,notify } from './store';
import type {Data} from './model';
import { viewSections,sectionLabel } from './presentation';
import { layoutLabels,cornerItems,surfaceItems,addressItems,addressHint } from './showcase';
import Segmented from './Segmented.vue';
import ShowcaseEditor from './ShowcaseEditor.vue';
import PageBodyEditor from './PageBodyEditor.vue';
import ImageField from './ImageField.vue';
const form=reactive<Data>({}),preview=ref<HTMLIFrameElement|null>(null),stage=ref<HTMLDivElement|null>(null),scale=ref(.4),cover=ref<string|null>(null),coverInput=ref<HTMLInputElement|null>(null),musicInput=ref<HTMLInputElement|null>(null),pageIndex=ref(0),articleIndex=ref(0),mode=ref('edit');
const showcaseSections=['home','server','images','showcase'],knownSections=['branding','colors','pages','music',...showcaseSections];
// Uploaded showcase images, shown in the editor and handed to the preview before they are published.
const images=computed<Data[]>(()=>desk.project?.presentationImages||desk.project?.branding?.presentationImages||[]);
const imageUrls=reactive<Record<string,string>>({});
const page=computed(()=>form.contentPages?.[pageIndex.value]);
const layoutOf=(item:Data)=>item.layout||(item.announcementPage?'ANNOUNCEMENTS':'MARKDOWN');
const colorFields=[{key:'accentColor',label:'强调色'},{key:'secondaryAccentColor',label:'辅助强调色'},{key:'titleColor',label:'标题文字'},{key:'topBarColor',label:'顶部背景'},{key:'cardColor',label:'内容卡片'}];
const modes=[{id:'edit',label:'编辑'},{id:'preview',label:'预览'}];
let draftProject='',seeding=false,resize:ResizeObserver|undefined;
function seed(){draftProject=desk.project?.id||'';seeding=true;const branding=desk.project?.branding||{};for(const key of Object.keys(form))delete form[key];Object.assign(form,JSON.parse(JSON.stringify(branding)));form.productName??=desk.project?.displayName;form.contentPages??=[];form.newsArticles??=[];form.welcomeText??='欢迎来到';form.accentColor??='#2ee8df';form.secondaryAccentColor??='#b06cff';form.brandName??='梦鱼更新器';form.brandEnglishName??='DreamingFish';form.titleColor??='#fff6e0';form.topBarColor??='#030708';form.cardColor??='#030708';form.topBarOpacity??=0.22;desk.settingsDirty=false;pageIndex.value=0;safely(loadCover);void nextTick(()=>{seeding=false;});}
async function loadCover(){if(cover.value){URL.revokeObjectURL(cover.value);cover.value=null;}if(desk.project?.branding?.coverObject){try{cover.value=URL.createObjectURL((await blob(apiPath('/cover'))).blob);}catch{}}sendPreview();}
function sendPreview(){preview.value?.contentWindow?.postMessage({type:'dfs-admin-preview',branding:{...JSON.parse(JSON.stringify(form))},backgroundUrl:cover.value,images:{...imageUrls}},location.origin);}
async function loadImages(){const names=new Set(images.value.map(i=>String(i.fileName)));for(const name of Object.keys(imageUrls))if(!names.has(name)){URL.revokeObjectURL(imageUrls[name]);delete imageUrls[name];}for(const name of names)if(!imageUrls[name]){try{imageUrls[name]=URL.createObjectURL((await blob(apiPath('/presentation-images/'+encodeURIComponent(name)))).blob);}catch{}}sendPreview();}
function setLook(key:string,value:string){form.theme={...(form.theme||{}),[key]:value};}
const previewReady=(event:MessageEvent)=>{if(event.origin===location.origin&&event.source===preview.value?.contentWindow&&event.data?.type==='dfs-player-preview-ready')sendPreview();};
watch(()=>desk.project?.id,seed,{immediate:true});watch(form,()=>{if(!seeding)desk.settingsDirty=true;void nextTick(sendPreview);},{deep:true});watch(()=>images.value.map(i=>i.fileName+':'+i.sha256).join(),()=>safely(loadImages),{immediate:true});
// The server keeps a field the page leaves out, so a cleared logo goes as an empty name.
async function save(){await saveProject({...form,brandLogoFile:form.brandLogoFile??''},draftProject);desk.settingsDirty=false;}
async function uploadCover(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await operation(async()=>{await binary(apiPath('/cover'),file);await loadProject();await loadCover();notify('背景图片已上传，检查并发布后生效');});}
async function uploadMusic(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await operation(async()=>{await binary(apiPath(`/music/upload?fileName=${encodeURIComponent(file.name)}&title=${encodeURIComponent(file.name.replace(/\.mp3$/i,''))}`),file);await loadProject();notify('音乐已上传，检查并发布后生效');});}
function addPage(layout='MARKDOWN'){const titles:Record<string,string>={MARKDOWN:'新页面',ANNOUNCEMENTS:'服务器公告',GALLERY:'玩家画廊',BLOCKS:'服务器介绍'},labels:Record<string,string>={MARKDOWN:'新页面',ANNOUNCEMENTS:'公告',GALLERY:'画廊',BLOCKS:'介绍'};form.contentPages.push({id:`page-${Date.now().toString(36)}`,navigationLabel:labels[layout],announcementPage:layout==='ANNOUNCEMENTS',layout:layout==='MARKDOWN'||layout==='ANNOUNCEMENTS'?null:layout,eyebrow:'',title:titles[layout],lead:'',markdown:'',articles:layout==='ANNOUNCEMENTS'?[]:null,gallery:layout==='GALLERY'?[]:null,blocks:layout==='BLOCKS'?[]:null});pageIndex.value=form.contentPages.length-1;articleIndex.value=0;}
function addArticle(){const page=form.contentPages[pageIndex.value];page.articles??=[];page.articles.push({id:`article-${Date.now().toString(36)}`,title:'新公告',summary:'',publishedOn:new Date().toISOString().slice(0,10),coverUrl:'',markdown:''});articleIndex.value=page.articles.length-1;}
async function clearCover(){await saveProject({...form,removeCover:true},draftProject);await loadCover();}
onMounted(()=>{window.addEventListener('message',previewReady);resize=new ResizeObserver(([entry])=>{scale.value=Math.min((entry.contentRect.width-32)/1280,(entry.contentRect.height-32)/800,1);});if(stage.value)resize.observe(stage.value);});onUnmounted(()=>{window.removeEventListener('message',previewReady);resize?.disconnect();if(cover.value)URL.revokeObjectURL(cover.value);for(const url of Object.values(imageUrls))URL.revokeObjectURL(url);});
</script>
<template><div class="view appearance-view" :class="`mode-${mode}`">
 <section class="stage preview-stage">
  <header class="stage-toolbar"><div class="stage-title"><span class="header-icon"><Monitor :size="16"/></span><div><strong>玩家端实时预览</strong><small>可以直接点击预览里的导航</small></div></div><span class="toolbar-spacer"/><span class="toolbar-note">保存后，玩家下次启动会获取</span><Segmented v-model="mode" class="mode-switch" :items="modes" label="编辑或预览"/></header>
  <div ref="stage" class="player-preview-stage"><iframe ref="preview" :style="{transform:`translate(-50%,-50%) scale(${Math.max(.05,scale)})`}" src="/player-preview/index.html?adminPreview=1" title="实际玩家端预览" @load="sendPreview"></iframe></div>
 </section>
 <aside class="side-card editor-card" aria-label="玩家端设计">
  <header class="card-header plain stacked"><strong class="section-title">{{sectionLabel('appearance',desk.section)}}</strong><div class="select-capsule wide section-tabs"><select v-model="desk.section" aria-label="设计分组"><option v-for="item in viewSections.appearance" :key="item.id" :value="item.id">{{item.label}}</option></select><ChevronDown :size="13"/></div><Segmented v-model="mode" class="mode-switch" :items="modes" label="编辑或预览"/></header>
  <form class="card-scroll appearance-form" @submit.prevent="safely(save)">
   <ShowcaseEditor v-if="showcaseSections.includes(desk.section)" :form="form" :section="desk.section" :images="images" :image-urls="imageUrls"/>
   <template v-else-if="desk.section==='branding'||!knownSections.includes(desk.section)"><h3>首页内容</h3><label>欢迎文字<input v-model="form.welcomeText" required></label><label>主标题<input v-model="form.productName" required></label><label>副标题<input v-model="form.subtitle"></label><label>Minecraft 服务器地址<input v-model="form.serverAddress" placeholder="例如 play.example.com"></label><label>首页显示地址<Segmented :model-value="form.addressPlacement||'CARD'" :items="addressItems" class="compact theme-switch" label="首页显示地址" @update:model-value="form.addressPlacement=$event"/><small>{{addressHint(form.addressPlacement,form.serverCard?.enabled!==false)}}</small></label><h3>窗口品牌</h3><div class="form-grid"><label>中文名称<input v-model="form.brandName" required></label><label>英文名称<input v-model="form.brandEnglishName" required></label></div><ImageField :target="form" :images="images" label="左上角图标" file-key="brandLogoFile" empty-label="使用梦鱼更新器图标" no-url/><small class="field-help">先在“展示图片”里上传方形图片再选择；图片随下次发布给玩家，发布前玩家仍看到梦鱼更新器图标。</small></template>
   <template v-else-if="desk.section==='colors'"><h3>配色</h3><div class="color-list"><label v-for="item in colorFields" :key="item.key" class="color-row"><input v-model="form[item.key]" type="color" :aria-label="item.label"><span>{{item.label}}</span><input v-model="form[item.key]" class="hex-input" :aria-label="item.label+'色值'"></label></div><label>顶部背景不透明度<div class="range-row"><input v-model.number="form.topBarOpacity" type="range" min="0" max="1" step=".01"><output>{{Math.round(form.topBarOpacity*100)}}%</output></div></label>
    <h3>卡片风格</h3><label>圆角<Segmented :model-value="form.theme?.corner||'ROUND'" :items="cornerItems" class="compact theme-switch" label="卡片圆角" @update:model-value="setLook('corner',$event)"/></label><label>质感<Segmented :model-value="form.theme?.surface||'GLASS'" :items="surfaceItems" class="compact theme-switch" label="卡片质感" @update:model-value="setLook('surface',$event)"/><small>首页卡片、更新区和内容块都会跟着变化。</small></label>
    <h3>背景图片</h3><div class="cover-control"><img v-if="cover" :src="cover" alt="玩家端背景"><div v-else class="cover-empty"><Image :size="24"/><span>使用默认背景</span></div><div class="cover-actions"><button type="button" @click="coverInput?.click()"><Upload :size="15"/>上传图片</button><button v-if="cover" type="button" class="text-action" @click="safely(clearCover)"><RotateCcw :size="14"/>恢复默认背景</button></div></div><input ref="coverInput" type="file" accept="image/*" hidden @change="safely(()=>uploadCover($event))"></template>
   <template v-else-if="desk.section==='pages'"><div class="page-controls"><div class="select-capsule wide"><select v-model.number="pageIndex" aria-label="编辑页面" :disabled="!form.contentPages?.length"><option v-if="!form.contentPages?.length" :value="0">还没有页面</option><option v-for="(page,i) in form.contentPages" :key="page.id" :value="i">{{page.navigationLabel}} · {{layoutLabels[layoutOf(page)]}}</option></select><ChevronDown :size="13"/></div><button type="button" class="icon-button filled" aria-label="新建图文页" title="新建图文页" @click="addPage('MARKDOWN')"><Plus :size="16"/></button></div>
    <div class="new-page-row"><button type="button" class="small" @click="addPage('ANNOUNCEMENTS')"><Megaphone :size="14"/>公告页</button><button type="button" class="small" @click="addPage('BLOCKS')"><Blocks :size="14"/>内容块页</button><button type="button" class="small" @click="addPage('GALLERY')"><Images :size="14"/>画廊页</button></div>
    <template v-if="page"><div class="form-grid"><label>导航名称<input v-model="page.navigationLabel" maxlength="24"></label><label>眉题<input v-model="page.eyebrow" maxlength="40" placeholder="页面标题上方的小字"></label></div><label>页面标题<input v-model="page.title" maxlength="60"></label><label>引导文字<textarea v-model="page.lead" rows="2" maxlength="300"></textarea></label>
     <PageBodyEditor v-if="['GALLERY','BLOCKS'].includes(layoutOf(page))" :page="page" :pages="form.contentPages" :images="images"/>
     <label v-else-if="layoutOf(page)==='MARKDOWN'">正文 Markdown<textarea v-model="form.contentPages[pageIndex].markdown" class="markdown-editor" rows="14" placeholder="在这里写下服务器规则、玩法或介绍"></textarea></label>
     <template v-else><div class="article-controls"><strong>公告文章</strong><button type="button" class="icon-button filled" aria-label="新建公告" title="新建公告" @click="addArticle"><Plus :size="16"/></button></div><div v-if="form.contentPages[pageIndex].articles?.length" class="select-capsule wide"><select v-model.number="articleIndex" aria-label="编辑公告"><option v-for="(article,i) in form.contentPages[pageIndex].articles" :key="article.id" :value="i">{{article.title}}</option></select><ChevronDown :size="13"/></div><template v-if="form.contentPages[pageIndex].articles?.[articleIndex]"><label class="spaced">公告标题<input v-model="form.contentPages[pageIndex].articles[articleIndex].title"></label><label>摘要<textarea v-model="form.contentPages[pageIndex].articles[articleIndex].summary" rows="2"></textarea></label><div class="form-grid"><label>分类<input v-model="form.contentPages[pageIndex].articles[articleIndex].category" maxlength="24" placeholder="例如 活动、维护"></label><label>作者<input v-model="form.contentPages[pageIndex].articles[articleIndex].author" maxlength="40"></label></div><div class="form-grid"><label>日期<input v-model="form.contentPages[pageIndex].articles[articleIndex].publishedOn" type="date"></label><label>封面地址<input v-model="form.contentPages[pageIndex].articles[articleIndex].coverUrl" type="url"></label></div><label>公告正文<textarea v-model="form.contentPages[pageIndex].articles[articleIndex].markdown" class="markdown-editor" rows="10"></textarea></label><button type="button" class="text-action danger-text" @click="form.contentPages[pageIndex].articles.splice(articleIndex,1);articleIndex=0"><Trash2 :size="14"/>移除这篇公告</button></template></template>
     <button type="button" class="text-action danger-text" @click="form.contentPages.splice(pageIndex,1);pageIndex=0"><Trash2 :size="14"/>移除这个页面</button></template>
    <div v-else class="empty-list compact"><span class="empty-art"><FileText :size="24"/></span><strong>添加一个玩家页面</strong><span>公告、规则、玩法与介绍都可以放在这里。</span></div></template>
   <template v-else><div class="music-heading"><h3>启动器播放列表</h3><button type="button" @click="musicInput?.click()"><Upload :size="15"/>上传 MP3</button></div><div class="music-list"><article v-for="track in desk.project?.branding?.musicTracks||[]" :key="track.id"><span class="track-art"><Music :size="16"/></span><div><strong>{{track.title}}</strong><small>{{track.fileName}}</small></div><button type="button" class="icon-button" :aria-label="`移除音乐 ${track.title}`" title="移除" @click="safely(async()=>{await request(apiPath('/music/'+encodeURIComponent(track.id)),'DELETE');await loadProject();})"><Trash2 :size="15"/></button></article><div v-if="!desk.project?.branding?.musicTracks?.length" class="empty-list compact"><span class="empty-art"><Music :size="24"/></span><strong>没有启动音乐</strong><span>选择 MP3，玩家端会按播放列表循环播放。</span></div></div><input ref="musicInput" type="file" accept=".mp3,audio/mpeg" hidden @change="safely(()=>uploadMusic($event))"></template>
  </form>
  <footer class="card-footer"><span class="save-state" :class="{dirty:desk.settingsDirty}"><i/>{{desk.settingsDirty?'尚未保存':'已全部保存'}}</span><button class="accent" :disabled="desk.busy" @click="safely(save)"><Save :size="15"/>保存</button></footer>
 </aside>
</div></template>
